'use strict';

// MODULES //

var log = require( '@stdlib/console/log' );


// MAIN //

/**
* Writes a rendered plot to `stdout`.
*
* @private
* @param {Object} plot - plot instance
* @param {Function} plot.render - method for rendering a plot to a string
*/
function view( plot ) {
	plot.render( onRender );

	/**
	* Callback invoked upon render completion.
	*
	* @private
	* @param {(Error|null)} error - error object or null
	* @param {string} result - result
	* @throws {Error} unexpected error
	*/
	function onRender( error, result ) {
		if ( error ) {
			throw error;
		}
		log( result );
	}
}


// EXPORTS //

module.exports = view;
